const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const chengdu = ee.Geometry.Point([104.06, 30.67]); // Approximate center of Chengdu
  const suining = ee.Geometry.Point([105.57, 30.51]); // Approximate center of Suining
  const startDate = '2001-01-01';
  const endDate = '2023-12-31';
  const bandName = 'AOD_550_Dark_Target_Deep_Blue_Combined_Mean'; // Aerosol Optical Depth at 550nm

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('MODIS/061/MOD08_M3')
    .filterDate(startDate, endDate)
    .select(bandName);

  const collectionSize = await collection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No MODIS AOD images found for the specified period.");
    console.log("C1");
    return;
  }

  // Calculate the mean AOD image over the entire period
  const meanAodImage = collection.mean();

  // 3. Processing & Calculation for Chengdu
  const chengduAodDict = await meanAodImage.reduceRegion({
    reducer: ee.Reducer.mean().setOutputs(['mean_aod']), // Set output name for clarity
    geometry: chengdu,
    scale: 1000, // MODIS resolution is ~10km, scale 1000 is appropriate
    maxPixels: 1e9,
    tileScale: 16 // Increase tileScale to avoid memory errors for large reductions
  }).getInfo();

  const chengduAod = chengduAodDict ? chengduAodDict['mean_aod'] : null;

  // Calculate pixel count for Chengdu
  const chengduPixelCountDict = await meanAodImage.select(bandName)
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: chengdu,
      scale: 1000,
      maxPixels: 1e9,
      tileScale: 16
    }).getInfo();
  const chengduPixels = chengduPixelCountDict ? chengduPixelCountDict[bandName] : 0;

  // 3. Processing & Calculation for Suining
  const suiningAodDict = await meanAodImage.reduceRegion({
    reducer: ee.Reducer.mean().setOutputs(['mean_aod']),
    geometry: suining,
    scale: 1000,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const suiningAod = suiningAodDict ? suiningAodDict['mean_aod'] : null;

  // Calculate pixel count for Suining
  const suiningPixelCountDict = await meanAodImage.select(bandName)
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: suining,
      scale: 1000,
      maxPixels: 1e9,
      tileScale: 16
    }).getInfo();
  const suiningPixels = suiningPixelCountDict ? suiningPixelCountDict[bandName] : 0;

  // 4. Validation & Final Answer
  if (chengduPixels === 0 || suiningPixels === 0) {
    console.log(`Chengdu valid pixels: ${chengduPixels}, Suining valid pixels: ${suiningPixels}`);
    console.log("No valid pixels after processing for one or both locations.");
    console.log("C2");
    return;
  }

  if (chengduAod === null || isNaN(chengduAod) || suiningAod === null || isNaN(suiningAod)) {
    console.log(`Chengdu AOD: ${chengduAod}, Suining AOD: ${suiningAod}`);
    console.log("Calculation resulted in None/NaN for AOD.");
    console.log("C3");
    return;
  }

  console.log(`MODIS AOD images: ${collectionSize}`);
  console.log(`Chengdu (Pixels: ${chengduPixels}): Mean AOD = ${chengduAod.toFixed(3)}`);
  console.log(`Suining (Pixels: ${suiningPixels}): Mean AOD = ${suiningAod.toFixed(3)}`);

  if (chengduAod > suiningAod) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
